// Performance tunables.
//  • ADVICE_MAX_SEARCHES caps web_search round-trips inside the model turn —
//    the single biggest latency lever. The prompt asks for 6–10; 8 is a good
//    speed/depth balance. Override with STOCKS_ADVICE_MAX_SEARCHES.
//  • CORRECTION_MODEL handles the (mostly mechanical) price/sizing card
//    rewrites — a fast Haiku here is much cheaper than the advice model.
const ADVICE_MAX_SEARCHES = Math.max(1, parseInt(process.env.STOCKS_ADVICE_MAX_SEARCHES, 10) || 8);
const CORRECTION_MODEL = process.env.STOCKS_CORRECTION_MODEL || "claude-haiku-4-5";

// ── token verification (same scheme as stocksPortfolio.js) ────────
function getSecret() {
  return process.env.STOCKS_SECRET || process.env.MEDICENTRE_SECRET || "";
}
function b64urlDecode(s) {
  s = String(s || "").replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  return Buffer.from(s, "base64");
}
function b64url(buf) {
  return buf.toString("base64").replace(/=+$/, "").replace(/\+/g, "-").replace(/\//g, "_");
}
function verifySessionToken(token) {
  const secret = getSecret();
  if (!secret) return null;
  const [body, sig] = String(token || "").split(".");
  if (!body || !sig) return null;
  const expected = b64url(crypto.createHmac("sha256", secret).update(body).digest());
  if (sig.length !== expected.length) return null;
  try {
    if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) return null;
  } catch { return null; }
  try {
    const payload = JSON.parse(b64urlDecode(body).toString("utf8"));
    if (payload?.sub !== "stocks-session") return null;
    if (typeof payload?.exp !== "number" || payload.exp < Math.floor(Date.now() / 1000)) return null;
    return payload;
  } catch { return null; }
}
function getSessionToken(req) {
  const cookie = req.headers?.cookie || "";
  const m = cookie.match(/(?:^|;\s*)stocks_session=([^;]+)/);
  if (m) { try { return decodeURIComponent(m[1]); } catch { return m[1]; } }
  const a = req.headers?.authorization || req.headers?.Authorization || "";
  return typeof a === "string" && a.startsWith("Bearer ") ? a.slice(7).trim() : null;
}
function requireStocksAuth(req, res, next) {
  const token = getSessionToken(req);
  if (!token) return res.status(401).json({ error: "Missing session credential" });
  const payload = verifySessionToken(token);
  if (!payload) return res.status(401).json({ error: "Invalid or expired session" });
  req.stocksUser = { email: payload.email.toLowerCase() };
  next();
}

// ── helpers ────────────────────────────────────────────────────────
function aggregateByTicker(positions, fx) {
  const m = {};
  for (const p of positions) {
    const val =
      p.ccy === "USD"
        ? (p.priceCad ?? (p.priceUsd ? p.priceUsd * fx : 0)) * (p.qty || 0)
        : (p.priceCad || 0) * (p.qty || 0);
    if (!m[p.ticker]) m[p.ticker] = { ticker: p.ticker, qty: 0, cad: 0 };
    m[p.ticker].qty += p.qty || 0;
    m[p.ticker].cad += val;
  }
  return Object.values(m).sort((a, b) => b.cad - a.cad);
}

// Phase 3+ retrofit: portfolioSummary in the routes file is a thin
// adapter over the canonical portfolio engine. Same return shape as
// before (total, agg, text, cashUsd, cashCad, cashCadEquiv,
// perAccountCash) — but every weight and total traces to
// computeCanonicalPortfolio, matching the briefing/audit/alpha paths.
function portfolioSummary(profile) {
  const canonical = computeCanonicalPortfolio(profile);
  const fx = profile.fxUsdCad || 1.37;
  if (!canonical) {
    return { total: 0, agg: [], text: "", cashUsd: 0, cashCad: 0, cashCadEquiv: 0, perAccountCash: [], canonical: null };
  }

  // Aggregate canonical positions by ticker for display (same ticker
  // in different accounts merges — legacy behavior).
  const byTicker = new Map();
  for (const pos of canonical.positions) {
    const key = pos.ticker;
    if (!byTicker.has(key)) {
      byTicker.set(key, { ticker: key, qty: 0, cad: 0, pct: 0, ccy: pos.currency, price: pos.price });
    }
    const a = byTicker.get(key);
    a.qty += pos.qty || 0;
    a.cad += pos.cad_value || 0;
    a.pct += pos.position_weight_pct || 0;
  }
  const rows = [...byTicker.values()].sort((a, b) => b.cad - a.cad);

  const lines = rows.map(r => {
    const pxStr = r.price ? `@ $${r.price.toFixed(2)} ${r.ccy}` : "";
    return `${r.ticker} (${r.ccy}): ${r.qty.toLocaleString()} sh ${pxStr} ≈ $${Math.round(r.cad).toLocaleString()} CAD (${r.pct.toFixed(1)}%)`;
  });

  const perAccountCash = [];
  for (const a of profile.accounts || []) {
    if ((a.cashUsd || 0) > 0 || (a.cashCad || 0) > 0) {
      perAccountCash.push(`  ${a.name}: $${(a.cashCad || 0).toFixed(0)} CAD, $${(a.cashUsd || 0).toFixed(0)} USD`);
    }
  }

  return {
    total: canonical.totals.book_cad,
    agg: rows.map(r => ({ ticker: r.ticker, qty: r.qty, cad: r.cad })),
    text: lines.join("\n"),
    cashUsd: canonical.cash.cash_usd_raw,
    cashCad: canonical.cash.cash_cad_raw,
    cashCadEquiv: canonical.cash.cash_cad_equiv,
    perAccountCash,
    canonical,
    fxUsdCad: fx,
  };
}

