// Parse a trade recommendation line out of a card body.
// Looks for:
//   Action: BUY 40 sh ENB. Entry: $75. Target: $84. Stop: $69. Horizon: 12 months
// Returns null if no actionable rec is present in the body.
// English stop-words the AI sometimes writes after the action verb that
// would otherwise be matched as tickers — "SELL ENTIRE", "HOLD CURRENT",
// "HOLD BOTH", "SELL ALL", "HOLD BUT". Must reject so the parser falls
// through to finding the real ticker later in the chunk (or drops).
const REC_STOP_WORD_TICKERS = new Set([
  "ALL","ANY","BOTH","BUT","CURRENT","ENTIRE","EVERY","NONE",
  "POSITION","POSITIONS","LOT","LOTS","REMAINING","RESERVE",
  "STOP","TARGET","ENTRY","ACTION","HORIZON","SOURCE",
  "USING","USES","INTO","FROM","BUY","SELL","HOLD","TRIM",
  "NEW","OLD","MORE","LESS","EITHER","NEITHER",
  "THE","AT","ON","TO","OF","FOR","WITH",
  "USD","CAD","EUR","GBP","RRSP","TFSA","RESP","FHSA",
  "MARKET","LIMIT","GTC","DAY","OCO",
]);

// Infer the rec's native currency so downstream price checks hit the right
// listing. A Canadian exchange suffix is decisive; otherwise look for an
// explicit "$NN CAD/USD" near the price. Returns null when unknown (the model
// default of USD then applies on save).
function detectRecCurrency(text, ticker) {
  if (/\.(TO|V|NE|CN)$/i.test(ticker || "")) return "CAD";
  const m = (text || "").match(/\$\s*[\d.,]+(?:\s*[-–]\s*\$?\s*[\d.,]+)?\s*(CAD|USD)\b/i);
  return m ? m[1].toUpperCase() : null;
}

// Map a stored rec to the exchange symbol to quote it on: CAD recs → .TO so
// "if-followed" P&L and target/stop alerts are checked on the right market.
function recSymbol(rec) {
  const t = String(rec?.ticker || "").toUpperCase();
  if (t.includes(".")) return t;
  return rec?.entryCurrency === "CAD" ? `${t}.TO` : t;
}

function parseRec(body) {
  if (!body || typeof body !== "string") return null;
  const m = body.match(/Action:\s*(BUY|SELL|TRIM|HOLD)\s*(\d[\d,]*)?\s*(?:sh)?\s*([A-Z][A-Z0-9.\-]{0,15})\b[^.]*?(?:Entry:\s*\$?([\d.]+))?[^.]*?(?:Target:\s*\$?([\d.]+))?[^.]*?(?:Stop:\s*\$?([\d.]+))?[^.]*?(?:Horizon:\s*([^.\n]+))?/i);
  if (!m) return null;
  const [, action, sharesStr, tickerRaw, entry, target, stop, horizon] = m;
  // Strip trailing dot — the ticker pattern allows `.` so it greedily captures
  // the sentence-ending period (e.g. "PLTR." instead of "PLTR").
  let ticker = String(tickerRaw || "").toUpperCase().replace(/\.+$/, "");
  if (REC_STOP_WORD_TICKERS.has(ticker)) {
    // Look deeper in the body for a real ticker — first uppercase 2-5 letter
    // token that isn't a stop-word.
    const scan = /\b([A-Z]{2,5}(?:\.[A-Z]{1,3})?)\b/g;
    let s, real = null;
    while ((s = scan.exec(body)) !== null) {
      const cand = s[1].toUpperCase().replace(/\.+$/, "");
      if (!REC_STOP_WORD_TICKERS.has(cand)) { real = cand; break; }
    }
    if (!real) return null; // no recoverable ticker — drop the rec
    ticker = real;
  }
  const shares = sharesStr ? parseInt(sharesStr.replace(/,/g, ""), 10) : null;
  // Derive horizon days
  let horizonDays = 30;
  if (horizon) {
    const h = horizon.toLowerCase();
    const num = parseInt(h.match(/(\d+)/)?.[1] || "0", 10) || 1;
    if (h.includes("day")) horizonDays = num;
    else if (h.includes("week")) horizonDays = num * 7;
    else if (h.includes("month")) horizonDays = num * 30;
    else if (h.includes("year")) horizonDays = num * 365;
  }
  const entryCurrency = detectRecCurrency(body, ticker);
  // Optional "Order timing:" line the AI may include in the narrative card,
  // matching the same enum the RECS JSON block uses.
  const timingMatch = body.match(/Order timing:\s*(pre-market|at-open|post-10am|gtc)\b/i);
  const orderTiming = timingMatch ? timingMatch[1].toLowerCase() : null;
  // Optional "Account:" line — the narrative-card equivalent of the
  // account field on the JSON block. Free-string on purpose (RRSP,
  // TFSA, Non-Spousal, "Non-Spousal USD"…). Trim whitespace, cap
  // length so a malformed multi-line capture can't blow up the row.
  const accountMatch = body.match(/^\s*Account:\s*([^\n\r]{1,60})/im);
  const account = accountMatch ? accountMatch[1].trim() : null;
  return {
    action: action.toUpperCase(),
    shares,
    ticker,
    entryPrice: entry ? parseFloat(entry) : null,
    targetPrice: target ? parseFloat(target) : null,
    stopPrice: stop ? parseFloat(stop) : null,
    horizonDays,
    ...(entryCurrency ? { entryCurrency } : {}),
    ...(orderTiming ? { orderTiming } : {}),
    ...(account ? { account } : {}),
  };
}

// Fetch current price for a ticker via the in-process price proxy
async function fetchCurrentPrice(ticker) {
  try {
    const url = `https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(ticker)}?interval=1d&range=1d`;
    const ctrl = new AbortController();
    const tid = setTimeout(() => ctrl.abort(), 5000);
    const r = await fetch(url, { signal: ctrl.signal, headers: { "User-Agent": "Mozilla/5.0 (Curriculate)" } });
    clearTimeout(tid);
    if (!r.ok) return null;
    const j = await r.json();
    return j?.chart?.result?.[0]?.meta?.regularMarketPrice ?? null;
  } catch { return null; }
}

// Compute hypothetical P&L on a recommendation given the current price.
// Sign convention: positive = the call was right.
function scorePnl(rec, currentPrice) {
  if (!rec.entryPrice || !currentPrice) return null;
  const raw = (currentPrice - rec.entryPrice) / rec.entryPrice;
  // SELL/TRIM: profit if price went DOWN
  if (rec.action === "SELL" || rec.action === "TRIM") return -raw;
  // BUY: profit if price went UP
  if (rec.action === "BUY") return raw;
  // HOLD: not directional, so 0 — we don't credit or debit holds
  return 0;
}

// Strip Claude web_search citation markers from model output.
// Web_search results include inline <cite index="...">...</cite> wrappers
// that we don't want appearing in advice card bodies — citations are
// returned separately as the `sources` array.
function stripCiteTags(s) {
  if (!s) return s;
  return s
    .replace(/<cite[^>]*>([\s\S]*?)<\/cite>/gi, "$1")
    .replace(/<\/?cite[^>]*>/gi, "")
    // also strip any stray Anthropic search-result reference markers
    .replace(/\[(?:cite[:_]?)?\d+(?:[-,]\d+)*\]/g, "");
}

// Extract first balanced JSON object from a string
// ── Post-validation: catch AI hallucinated/stale prices ─────────────
//
// The AI claims "(verified)" but doesn't actually web_search reliably.
// User has caught: SQ deprecated, ROKU $67→actual $128, META $525→$608,
// VZ $42→$47, TD.TO $85→$150, XLU $74→$44, FTS.TO $62→$77. After every
// AI response we extract every (TICKER, quoted-price) pair from the
// cards, fetch the current price from FMP (the paid premium feed; Yahoo
// is a fallback only if FMP doesn't have the symbol), and attach a
// warning to each card with mismatches >10% so the UI can red-banner
// the rec before the user trades on it.

