// ─────────────────────────────────────────────────────────────────────
// GET /api/stocks-advice/source-scorecard?days=90
//
// "Baseball cards" — aggregate every CLOSED rec (target-hit, stop-hit,
// expired) by sourceLabel over the window. For each source, compute:
//   trades, wins, losses, winRate, avgReturnPct, medianReturnPct,
//   maxDrawdownPct (worst single trade), expectancyPct
//     (= winRate × avgWin − (1-winRate) × |avgLoss|)
//
// The "return" for each closed rec is:
//   BUY:  (hitPrice - entryPrice) / entryPrice × 100
//   SELL: (entryPrice - hitPrice) / entryPrice × 100  (short-style)
// So a positive return = the rec would have made money if executed at
// entry and closed at hit.
//
// Feedback loop that lets you retire sources that don't earn their spot.
// Feeds the source-comparison "baseball cards" table on Performance.
// ─────────────────────────────────────────────────────────────────────
router.get("/source-scorecard", requireStocksAuth, async (req, res) => {
  try {
    const days = Math.min(Math.max(parseInt(req.query.days, 10) || 90, 7), 730);
    const since = new Date(Date.now() - days * 86400 * 1000);
    const recs = await StocksAdviceRec.find({
      email: req.stocksUser.email,
      generatedAt: { $gte: since },
      status: { $in: ["target-hit", "stop-hit", "expired"] },
      entryPrice: { $gt: 0 },
      hitPrice: { $gt: 0 },
    }).select("sourceLabel action entryPrice hitPrice status").lean();

    const bySource = new Map();
    for (const r of recs) {
      const label = r.sourceLabel || "unlabeled";
      if (!bySource.has(label)) bySource.set(label, []);
      const dir = r.action === "BUY" ? 1 : -1;
      const retPct = ((r.hitPrice - r.entryPrice) / r.entryPrice) * 100 * dir;
      if (!Number.isFinite(retPct)) continue;
      bySource.get(label).push({ retPct, status: r.status });
    }

    const rows = [];
    for (const [label, arr] of bySource.entries()) {
      const trades = arr.length;
      if (trades === 0) continue;
      const wins = arr.filter(x => x.retPct > 0);
      const losses = arr.filter(x => x.retPct <= 0);
      const winRate = trades > 0 ? (wins.length / trades) * 100 : 0;
      const avgReturnPct = arr.reduce((s, x) => s + x.retPct, 0) / trades;
      const avgWin = wins.length ? wins.reduce((s, x) => s + x.retPct, 0) / wins.length : 0;
      const avgLoss = losses.length ? losses.reduce((s, x) => s + x.retPct, 0) / losses.length : 0;
      const worstTradePct = arr.reduce((min, x) => x.retPct < min ? x.retPct : min, 0);
      const expectancyPct = (winRate / 100) * avgWin + ((100 - winRate) / 100) * avgLoss;
      const sorted = [...arr].map(x => x.retPct).sort((a, b) => a - b);
      const medianReturnPct = trades % 2 === 0
        ? (sorted[trades / 2 - 1] + sorted[trades / 2]) / 2
        : sorted[Math.floor(trades / 2)];
      rows.push({
        source: label,
        trades,
        winRate: Number(winRate.toFixed(1)),
        avgReturnPct: Number(avgReturnPct.toFixed(2)),
        medianReturnPct: Number(medianReturnPct.toFixed(2)),
        avgWinPct: Number(avgWin.toFixed(2)),
        avgLossPct: Number(avgLoss.toFixed(2)),
        worstTradePct: Number(worstTradePct.toFixed(2)),
        expectancyPct: Number(expectancyPct.toFixed(3)),
        proven: trades >= 20,
      });
    }
    // Sort by expectancy descending — best source at top. Ties broken by trades.
    rows.sort((a, b) => (b.expectancyPct - a.expectancyPct) || (b.trades - a.trades));

    res.json({
      ok: true,
      windowDays: days,
      windowStart: since,
      rows,
      totalRecsInWindow: recs.length,
      generatedAt: new Date(),
    });
  } catch (err) {
    console.error("stocks-advice source-scorecard error:", err);
    res.status(500).json({ error: "Internal error" });
  }
});

// ─────────────────────────────────────────────────────────────────────
// GET /api/stocks-advice/scorecard?days=30
//
// For each rec in the window:
//   - Is there a trade journal entry with linkedAdviceRecId == rec._id?
//     → if yes: "followed". Compute realized/unrealized P&L from cost.
//     → if no:  "skipped". Compute hypothetical P&L (would-have-been).
//   - What's the rec's current status? (open / target-hit / stop-hit)
//
// Aggregates: count of followed vs skipped, total $ P&L attributable to
// advice taken, opportunity cost of advice skipped.
// ─────────────────────────────────────────────────────────────────────
router.get("/scorecard", requireStocksAuth, async (req, res) => {
  try {
    const days = Math.min(Math.max(parseInt(req.query.days, 10) || 30, 7), 365);
    const since = new Date(Date.now() - days * 86400 * 1000);

    const [recs, trades] = await Promise.all([
      StocksAdviceRec.find({ email: req.stocksUser.email, generatedAt: { $gte: since } }).lean(),
      StocksTradeJournal.find({ email: req.stocksUser.email, executedAt: { $gte: since } }).lean(),
    ]);

    if (recs.length === 0) {
      return res.json({
        days,
        summary: { total: 0, followed: 0, skipped: 0, pending: 0,
                   followedPnlPct: null, skippedPnlPct: null,
                   netDollarsFromFollowed: 0, netDollarsFromSkipped: 0 },
        items: [],
      });
    }

    // Build a quick lookup: rec _id (string) → trade journal entry.
    // Primary pass: explicit linkedAdviceRecId (the ID auto-link path).
    const tradesByRecId = new Map();
    for (const t of trades) {
      if (t.linkedAdviceRecId) tradesByRecId.set(String(t.linkedAdviceRecId), t);
    }

    // Secondary pass — fuzzy-link recs to trades that DIDN'T get the
    // explicit linkedAdviceRecId set. Common when:
    //   - user manually entered a SU.TO trade for a "SU" rec (base
    //     ticker mismatch, since fixed but historical trades are stuck)
    //   - poller ingested a trade before the position-update fix
    //   - CSV import didn't carry the rec id
    //
    // Match criteria: base ticker + action side + trade date within
    // [rec.generatedAt, rec.generatedAt + 21d].
    //
    // IMPORTANT — one trade CAN satisfy multiple recs. If the AI
    // recommended SELL NVDA Mon, Tue, Wed and the user finally sold
    // Wednesday, that single SELL fulfills all three recs — the trader
    // followed the guidance, just on a delayed timeline. Only trades
    // that ALREADY had an explicit linkedAdviceRecId (from Execute-
    // click) are reserved to their original rec so we don't
    // double-count the same rec.
    const baseTicker = (t) => String(t || "").toUpperCase().replace(/\..*$/, "").replace(/[^A-Z0-9]/g, "");
    for (const rec of recs) {
      if (tradesByRecId.has(String(rec._id))) continue; // already linked
      const recBase = baseTicker(rec.ticker);
      const recDate = new Date(rec.generatedAt);
      const cutoffDate = new Date(recDate.getTime() + 21 * 86400000);
      const fuzzyMatch = trades.find(t => {
        const executedAt = new Date(t.executedAt);
        if (executedAt < recDate || executedAt > cutoffDate) return false;
        return (t.legs || []).some(leg =>
          leg.side === rec.action &&
          baseTicker(leg.ticker) === recBase
        );
      });
      if (fuzzyMatch) {
        tradesByRecId.set(String(rec._id), fuzzyMatch);
      }
    }

    // Fetch current prices once per unique resolved symbol (CAD recs → .TO).
    // We also collect the extra listings implied by any actually-executed
    // trade leg, so a rec that got journaled as CAD-listing can still be
    // graded against its true USD-listing fill price (or vice versa).
    // Without this, an ENB BUY filled on NYSE at $55.49 USD but journaled
    // as CAD would grade against ENB.TO $79 CAD → phantom +42% gain.
    const symbols = new Set(recs.map(r => recSymbol(r)).filter(Boolean));
    const baseOfSym = (t) => String(t || "").toUpperCase().replace(/\..*$/, "").replace(/[^A-Z0-9]/g, "");
    for (const t of trades) {
      for (const leg of t.legs || []) {
        const base = baseOfSym(leg.ticker);
        if (!base) continue;
        if (leg.currency === "CAD") symbols.add(`${base}.TO`);
        else symbols.add(base);
      }
    }
    const priceMap = {};
    await Promise.all([...symbols].map(async sym => { priceMap[sym] = await fetchCurrentPrice(sym); }));

    const items = [];
    let followedCount = 0, skippedCount = 0, pendingCount = 0;
    let followedPnlAcc = 0, followedDollars = 0;
    let skippedPnlAcc = 0, skippedDollars = 0;

    for (const rec of recs) {
      const linkedTrade = tradesByRecId.get(String(rec._id));
      const followed = !!linkedTrade;
      const recBase = baseTicker(rec.ticker);

      // Find the matching leg by BASE ticker so an "ENB" rec pairs with
      // an "ENB.TO" leg (and vice versa). The old exact-match version
      // silently fell through and let the rec.entryPrice/entryCurrency
      // pair drive P&L math — which was a phantom-gain generator when
      // rec.entryCurrency and the actual fill currency disagreed.
      const followedLeg = followed
        ? (linkedTrade.legs || []).find(l => baseTicker(l.ticker) === recBase && (l.side === rec.action || (rec.action === "TRIM" && l.side === "SELL")))
          || (linkedTrade.legs || []).find(l => baseTicker(l.ticker) === recBase)
        : null;

      // Pick the current-price listing that matches the *actual fill*
      // currency, not the rec's saved entryCurrency. This is the fix for
      // the ENB "+42%" scorecard row: a NYSE-USD fill was being graded
      // against the TSX-CAD current price because the rec had been
      // journaled with entryCurrency="CAD".
      const priceLookupSym = followedLeg
        ? (followedLeg.currency === "CAD" ? `${recBase}.TO` : recBase)
        : recSymbol(rec);
      const currentPrice = priceMap[priceLookupSym];

      // Hypothetical P&L: how the rec WOULD have performed (entry → current)
      // - BUY rec: gain if price went UP from entry
      // - SELL/TRIM rec: gain if price went DOWN from entry (sell was right)
      // Uses recSymbol-based current price so the hypo lookup matches the
      // currency the rec was WRITTEN in, even when no leg was followed.
      let hypoPnlPct = null, hypoDollars = null;
      const hypoCurrent = priceMap[recSymbol(rec)];
      if (rec.entryPrice && hypoCurrent) {
        const raw = (hypoCurrent - rec.entryPrice) / rec.entryPrice;
        const dir = (rec.action === "BUY") ? 1 : (rec.action === "SELL" || rec.action === "TRIM") ? -1 : 0;
        hypoPnlPct = dir * raw * 100;
        if (rec.shares) {
          hypoDollars = dir * (hypoCurrent - rec.entryPrice) * rec.shares;
        }
      }

      // Actual P&L if followed: use the actual fill price from the trade,
      // compared against the current price in that SAME currency listing.
      let actualPnlPct = null, actualDollars = null;
      if (followed && currentPrice && followedLeg && followedLeg.pricePerShare) {
        const raw = (currentPrice - followedLeg.pricePerShare) / followedLeg.pricePerShare;
        const dir = (followedLeg.side === "BUY") ? 1 : -1;
        actualPnlPct = dir * raw * 100;
        actualDollars = dir * (currentPrice - followedLeg.pricePerShare) * (followedLeg.shares || 0);
      }

      // Categorize
      if (followed) {
        followedCount++;
        if (actualPnlPct != null) {
          followedPnlAcc += actualPnlPct;
          followedDollars += actualDollars || 0;
        }
      } else {
        // Skipped: outcome based on hypothetical
        skippedCount++;
        if (hypoPnlPct != null) {
          skippedPnlAcc += hypoPnlPct;
          skippedDollars += hypoDollars || 0;
        }
      }

      // Time-context: how much of the rec's horizon has elapsed. Many
      // recs are 1-4 days old with 14-30d horizons; judging their
      // outcome as "underwater" today is premature by construction.
      const daysElapsed = Math.max(0, Math.round((Date.now() - new Date(rec.generatedAt).getTime()) / 86400000));
      const horizonDays = rec.horizonDays || 30;
      const horizonPct = horizonDays > 0 ? Math.min(100, (daysElapsed / horizonDays) * 100) : null;

      items.push({
        recId: String(rec._id),
        generatedAt: rec.generatedAt,
        ticker: rec.ticker,
        action: rec.action,
        shares: rec.shares,
        entryPrice: rec.entryPrice,
        targetPrice: rec.targetPrice,
        stopPrice: rec.stopPrice,
        horizonDays,
        currentPrice,
        status: rec.status || "open",
        followed,
        // Whether the followed link came from explicit recId (strong) or
        // fuzzy fallback (weaker). Lets the UI note "auto-linked" for
        // trades that lacked the explicit ID but still fulfilled the rec.
        followedVia: followed ? (linkedTrade.linkedAdviceRecId ? "explicit-recId" : "fuzzy-base-ticker") : null,
        hypoPnlPct,
        hypoDollars,
        actualPnlPct,
        actualDollars,
        tradeFillPrice: followed && followedLeg ? (followedLeg.pricePerShare || null) : null,
        tradeFillCurrency: followed && followedLeg ? (followedLeg.currency || null) : null,
        tradeShares: followed && followedLeg ? (followedLeg.shares || null) : null,
        tradeExecutedAt: followed ? linkedTrade.executedAt : null,
        daysElapsed,
        horizonPct,
      });
    }

    items.sort((a, b) => new Date(b.generatedAt) - new Date(a.generatedAt));

    // Time-aware verdict — the old "underwater" label fired even when
    // every rec was 1-5 days old with 14-30d horizons, which is a
    // punitive frame that doesn't match the actual signal:strength
    // question. Replace with a nuanced take that separates:
    //   • Prematurity: too early to judge (avg horizon % low)
    //   • Split narrative: followed vs skipped may tell different stories
    //   • Genuine underperformance: only when a majority is well into
    //     horizon (>60%) AND net negative
    const avgHorizonPctElapsed = items.length > 0
      ? items.reduce((s, i) => s + (i.horizonPct || 0), 0) / items.length
      : 0;
    const followedNet = followedDollars;
    const skippedNet = skippedDollars;
    let verdictSlug = "insufficient-data";
    let verdictMessage = "Not enough closed cycles to grade the strategy yet.";
    if (avgHorizonPctElapsed < 30) {
      verdictSlug = "too-early";
      verdictMessage = `Most recs are ${Math.round(avgHorizonPctElapsed)}% into their stated horizon — outcomes are unrealized. Check back once the average rec is past its horizon midpoint.`;
    } else if (followedNet >= 0 && skippedNet < 0) {
      verdictSlug = "followed-outperforming";
      verdictMessage = "Followed recs are net positive; skipped ones would have lost money. This is the intended signal quality.";
    } else if (followedNet >= 0 && skippedNet >= 0) {
      verdictSlug = "cohort-green";
      verdictMessage = "Whole cohort is net positive — both followed and skipped recs would have made money.";
    } else if (followedNet < 0 && skippedNet >= 0) {
      verdictSlug = "adverse-selection";
      verdictMessage = "The recs you took underperformed the ones you skipped. Consider what filter you're applying at the Execute step.";
    } else if (avgHorizonPctElapsed >= 60) {
      verdictSlug = "underperforming";
      verdictMessage = "Cohort is well into horizon and net negative on both followed + skipped. This is the honest bad-signal read.";
    } else {
      verdictSlug = "mid-cycle-drawdown";
      verdictMessage = `Currently down but cohort is only ${Math.round(avgHorizonPctElapsed)}% through horizon on average — several positions still have time to work.`;
    }

    res.json({
      days,
      summary: {
        total: recs.length,
        followed: followedCount,
        skipped: skippedCount,
        pending: pendingCount,
        followRate: recs.length > 0 ? (followedCount / recs.length) * 100 : 0,
        avgFollowedPnlPct: followedCount > 0 ? followedPnlAcc / followedCount : null,
        avgSkippedPnlPct: skippedCount > 0 ? skippedPnlAcc / skippedCount : null,
        netDollarsFromFollowed: followedDollars,
        netDollarsFromSkipped: skippedDollars,
        avgHorizonPctElapsed,
        verdict: { slug: verdictSlug, message: verdictMessage },
      },
      items,
    });
  } catch (err) {
    console.error("scorecard error:", err);
    res.status(500).json({ error: `Internal: ${err?.message || err}` });
  }
});

